// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts1, address actor) public {
        ts1 = bound(ts1, 2, type(uint256).max / 4);
        vm.assume(actor != address(0) && actor != address(c));

        vm.deal(actor, 20 ether);

        // first successful call at timestamp ts1
        vm.roll(1);
        vm.warp(ts1);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        uint256 before = c.pastBlockTime();

        // second successful call in the SAME block but at a strictly later timestamp
        vm.roll(1);
        vm.warp(ts1 + 1);
        vm.prank(actor);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok2);

        // GENERAL RULE: the recorded pastBlockTime strictly increases between
        // two successful calls at increasing timestamps (it records timestamps).
        assertTrue(c.pastBlockTime() > before);
    }
}
